mapper.select:
SELECT r.review_id AS reviewId, r.scenic_id AS scenicId, r.user_id AS userId, r.rating, r.content, r.images, r.status, r.created_at AS createdAt, r.updated_at AS updatedAt, r.reply_to AS replyTo, u.username, u.avatar_url AS avatarUrl FROM scenic_reviews r LEFT JOIN users u ON u.user_id = r.user_id WHERE r.status = 1
AND r.scenic_id = #{scenicId}
ORDER BY r.created_at DESC
